1	/** Families whose OsTemplate rows are game servers. Plain module (safe to import
2	 *  from server components and "use server" action files alike). */
3	export const GAME_FAMILIES = ["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"] as const;
4	export type GameFamily = (typeof GAME_FAMILIES)[number];
