3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import {
7	  familyFor,
8	  schemaFor,
9	  isValidVariant,
10	  validateConfig,
11	  type FamilySchema,
12	} from "./game-config";
13	
14	/**
15	 * Per-game customization actions (MVP).
16	 *
17	 * Customers pick a server *variant* (loader/flavour) and tune a small set of
18	 * game settings from the portal. Saving validates against the family schema
19	 * (lib/game-config.ts), persists `Server.gameVariant` + `Server.gameConfig`, and
20	 * enqueues a GAME_CONFIG job that the worker applies (simulated in MVP).
21	 *
22	 * Ownership + the "one in-flight job per server" invariant mirror
23	 * lib/actions-server-lifecycle.ts.
24	 */
25	
26	/** Owner (or admin) resolution — includes the relations `familyFor` needs. */
27	async function ownedServer(serverId: string) {
28	  const user = await requireUser();
29	  const server = await db.server.findUnique({
30	    where: { id: serverId },
31	    include: { osTemplate: true, gamePlan: true },
32	  });
33	  if (!server) throw new Error("Not found");
34	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
35	  return { user, server };
36	}
37	
38	async function hasInflightJob(serverId: string): Promise<boolean> {
39	  const pending = await db.job.count({
40	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
41	  });
42	  return pending > 0;
43	}
44	
45	export type GameConfigView = {
46	  family: string;
47	  schema: FamilySchema;
48	  variant: string;
49	  values: Record<string, string | number | boolean>;
50	};
51	
52	/**
53	 * Load the current customization state for an owned game server: the resolved
54	 * family + its schema, the selected variant (defaulting to the schema default)
55	 * and the stored settings values (validated/normalised against the schema so the
56	 * UI always gets a complete, well-typed object).
57	 */
58	export async function getGameConfig(
59	  serverId: string
60	): Promise<{ error?: string; config?: GameConfigView }> {
61	  const { server } = await ownedServer(serverId);
62	
63	  const family = familyFor(server);
64	  const schema = schemaFor(family);
65	  if (!family || !schema) {
66	    return { error: "This server doesn't support game settings." };
67	  }
68	
69	  const variant =
70	    server.gameVariant && isValidVariant(family, server.gameVariant)
71	      ? server.gameVariant
72	      : schema.defaultVariant;
73	
74	  const validated = validateConfig(family, (server.gameConfig as Record<string, unknown> | null) ?? {});
75	  const values = validated.ok ? validated.values : {};
76	
77	  return { config: { family, schema, variant, values } };
78	}
79	
80	/**
81	 * Validate and persist a server's game variant + settings, then enqueue a
82	 * GAME_CONFIG job to apply them. Refuses while another job is in flight.
83	 */
84	export async function saveGameConfig(
85	  serverId: string,
86	  variant: string,
87	  values: Record<string, unknown>
88	): Promise<{ error?: string; ok?: boolean }> {
89	  const { user, server } = await ownedServer(serverId);
90	
91	  const family = familyFor(server);
92	  const schema = schemaFor(family);
93	  if (!family || !schema) {
94	    return { error: "This server doesn't support game settings." };
95	  }
96	
97	  if (!isValidVariant(family, variant)) {
98	    return { error: "Pick a valid server type for this game." };
99	  }
100	
101	  const validated = validateConfig(family, values);
102	  if (!validated.ok) return { error: validated.error };
103	
104	  if (await hasInflightJob(serverId)) {
105	    return { error: "Another operation is already in progress on this server." };
106	  }
107	
108	  await db.server.update({
109	    where: { id: server.id },
110	    data: { gameVariant: variant, gameConfig: validated.values as any },
111	  });
112	  await db.job.create({ data: { type: "GAME_CONFIG", serverId: server.id } });
113	  await db.auditLog.create({
114	    data: {
115	      userId: user.id,
116	      action: "gameserver.config",
117	      detail: `${serverId} family=${family} variant=${variant}`,
118	    },
119	  });
120	
121	  revalidatePath(`/dashboard/servers/${serverId}`);
122	  return { ok: true };
123	}
