=== game-update-verify.ts ===
import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Game auto-update: the remote script, its output parser, and the verdict.
 *
 * INCIDENT ("Game auto-update cannot fail", honest inventory #3): the old
 * `updateCommand` returned
 *
 *     set -e; <steam>; <restart>; true
 *
 * where the steamcmd call ended `|| true` and was skipped entirely when steamcmd
 * was absent, every restart branch ended `|| true`, and the whole command ended
 * `; true`. The remote command could NOT exit non-zero. So `gameUpdate` always
 * reached its notification and always told the customer *"The latest server
 * update was applied and the service was restarted."* — for a box where steamcmd
 * was not installed, where no matching systemd unit existed, or where the service
 * came back dead. This runs unattended every 6 hours.
 *
 * `worker/apps.ts` is the model this follows: every operation declares what it
 * PROVES, the remote side emits explicit markers, and an exit code of 0 is never
 * accepted as evidence. (`wp_die()` prints its error and exits 0 — that is the
 * lesson, and `|| true` is the same lesson wearing a different hat.)
 *
 * A second honesty problem is fixed here too: minecraft and terraria have no
 * steamcmd app id, so for those families the job never updated ANYTHING — it
 * restarted a service. The success message now says which of the two happened.
 *
 * Pure and dependency-free: no SSH, no clock. Covered by test/game-update.test.ts,
 * which also runs `sh -n` and `dash -n` over the generated script.
 */

/** Steam dedicated-server app IDs for steamcmd-based families. */
export const STEAM_APPID: Partial<Record<GameFamily, string>> = {
  valheim: "896660",
  rust: "258550",
  palworld: "2394010",
  cs2: "730",
};

/** systemd service name candidates per family (first that exists wins). */
export const SERVICE_HINT: Record<GameFamily, string> = {
  minecraft: "minecraft",
  valheim: "valheim",
  rust: "rust",
  palworld: "palworld",
  cs2: "cs2",
  terraria: "terraria",
};

/** Does this family have an update source at all, or is the job only a restart? */
export function updatesFromSteam(family: GameFamily): boolean {
  return Boolean(STEAM_APPID[family]);
}

/** Seconds we wait for the unit to come back before we stop claiming anything. */
export const RESTART_WAIT_TRIES = 30;
export const RESTART_WAIT_SLEEP_S = 2;

/**
 * Build the remote script.
 *
 * Design rules, each of which the old one-liner broke:
 *
 *  - No `set -e` and no trailing `; true`. Control flow is explicit, and the exit
 *    status is irrelevant — the MARKERS are the contract, so a truncated or
 *    dropped connection is detectable (no `NXGU:END`) rather than indistinguishable
 *    from success.
 *  - steamcmd's own exit code is not trusted (it is famously unreliable and
 *    frequently non-zero on a perfectly good update). We match its own success
 *    line instead, and report the code alongside.
 *  - "no unit matched" is an outcome we emit, not a branch we swallow.
 *  - The post-restart state is polled and reported verbatim. `active` is the only
 *    thing that will be called success upstream.
 *
 * `family` is constrained to GAME_FAMILIES by the caller AND re-checked here, so
 * nothing unvalidated is interpolated into the shell.
 */
export function updateCommand(family: GameFamily): string {
  if (!GAME_FAMILIES.includes(family)) throw new Error(`not a game family: ${family}`);
  const appId = STEAM_APPID[family];
  const svc = SERVICE_HINT[family];
  // Both are compile-time constants from the tables above — never customer input.

  // Emitted by every branch that must not go on to restart the service.
  const stopHere = [
    `st=$(systemctl is-active "$unit" 2>/dev/null)`,
    `say "SKIPPED_RESTART:1"`,
    `say "STATE:${"$"}{st:-unknown}"`,
    `say "END"`,
    `exit 0`,
  ];

  const steam = appId
    ? [
        `fresh=0`,
        `if command -v steamcmd >/dev/null 2>&1; then`,
        `  out=$(steamcmd +login anonymous +app_update ${appId} validate +quit 2>&1); rc=$?`,
        `  say "STEAM_RC:$rc"`,
        // steamcmd prints "Success! App '<id>' already up to date." when there was
        // nothing to download, and "Success! App '<id>' fully installed." when
        // there was. Both used to match one grep, so the two outcomes were
        // indistinguishable — see the CURRENT/OK split in the header note.
        `  if printf '%s' "$out" | grep -q "Success! App '${appId}' already up to date"; then`,
        `    say "STEAM:CURRENT"`,
        `  elif printf '%s' "$out" | grep -q "Success! App '${appId}'"; then`,
        `    fresh=1; say "STEAM:OK"`,
        `  else`,
        `    say "STEAM:FAIL"`,
        `    printf '%s' "$out" | grep -i 'error' | head -3 | while IFS= read -r l; do say "STEAM_ERR:$l"; done`,
        `  fi`,
        `else`,
        `  say "STEAM:ABSENT"`,
        `fi`,
        // Do NOT bounce a healthy game server for an update that did not happen:
        // a restart kicks every connected player off for nothing, and it would
        // make "the service was restarted" the only true half of a false claim.
        // This now also covers the "already up to date" case, which is the COMMON
        // one — it ran every 6 hours and disconnected everybody four times a day.
        `if [ "$fresh" != "1" ]; then`,
        ...stopHere.map((l) => `  ${l}`),
        `fi`,
      ].join("\n")
    : [
        // No update source exists for this family, so there is nothing a restart
        // could apply. Restarting anyway is a pure loss: every connected player
        // is disconnected, four times a day, forever, to change nothing. The
        // rule two paragraphs up applies here MOST, and used not to be applied
        // here at all.
        `say "STEAM:NA"`,
        ...stopHere,
      ].join("\n");

  return [
    `say() { printf 'NXGU:%s\\n' "$1"; }`,
    // 1. Resolve the unit. `systemctl cat` succeeds only for a unit that exists.
    `unit=""`,
    `for c in ${svc} ${svc}-server; do`,
    `  if systemctl cat "$c" >/dev/null 2>&1; then unit="$c"; break; fi`,
    `done`,
    `if [ -z "$unit" ]; then`,
    `  unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${family} | head -1 | awk '{print $1}')`,
    `fi`,
    `if [ -z "$unit" ]; then say "UNIT:NONE"; say "END"; exit 0; fi`,
    `say "UNIT:$unit"`,
    `was=$(systemctl is-active "$unit" 2>/dev/null); say "WAS:${"$"}{was:-unknown}"`,
    // 2. Update the game files, where such a thing exists.
    steam,
    // 3. Restart, and report the real result of the restart call.
    `systemctl restart "$unit" >/dev/null 2>&1; say "RESTART_RC:$?"`,
    // 4. Wait for it to settle. A game server can take a while to open its port,
    //    so "activating" is a distinct answer from "failed" and both are reported.
    `i=0; st=""`,
    `while [ $i -lt ${RESTART_WAIT_TRIES} ]; do`,
    `  st=$(systemctl is-active "$unit" 2>/dev/null)`,
    `  if [ "$st" = "active" ] || [ "$st" = "failed" ]; then break; fi`,
    `  i=$((i+1)); sleep ${RESTART_WAIT_SLEEP_S}`,
    `done`,
    `say "STATE:${"$"}{st:-unknown}"`,
    `say "END"`,
  ].join("\n");
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

export type GameUpdateFacts = {
  /** The systemd unit the script acted on, or null when nothing matched. */
  unit: string | null;
  /** `systemctl is-active` before the restart. */
  wasActive: string;
  /** Exit code of `systemctl restart`, or null when it never ran. */
  restartRc: number | null;
  /** `systemctl is-active` after the restart, settled or timed out. */
  state: string;
  /**
   * "ok" = steamcmd downloaded a NEW build. "current" = it confirmed the server
   * was already up to date and downloaded nothing. Collapsing those two into one
   * value is what made "<game> updated on <host>" fire every 6 hours forever.
   */
  steam: "ok" | "current" | "failed" | "absent" | "na" | "unknown";
  steamRc: number | null;
  steamErrors: string[];
  /** Did the script run to completion? No END marker means we know nothing. */
  complete: boolean;
};

export function parseGameUpdateOutput(out: string): GameUpdateFacts {
  const text = String(out ?? "");
  const one = (re: RegExp): string | null => re.exec(text)?.[1] ?? null;

  const steamRaw = one(/^NXGU:STEAM:(\w+)$/m);
  const steam =
    steamRaw === "OK" ? "ok"
    : steamRaw === "CURRENT" ? "current"
    : steamRaw === "FAIL" ? "failed"
    : steamRaw === "ABSENT" ? "absent"
    : steamRaw === "NA" ? "na"
    : "unknown";

