23	  serverId: string;
24	  schema: FamilySchema;
25	  variant: string;
26	  values: Values;
27	  disabled?: boolean;
28	}) {
29	  const router = useRouter();
30	  const [variant, setVariant] = useState(initialVariant);
31	  const [values, setValues] = useState<Values>(initialValues);
32	  const [error, setError] = useState<string | null>(null);
33	  const [saved, setSaved] = useState(false);
34	  const [pending, start] = useTransition();
35	
36	  // Fields grouped by their `group` heading, preserving declaration order.
37	  const groups = useMemo(() => {
38	    const map = new Map<string, ConfigField[]>();
