73	            some settings only take effect after the next restart.
74	          </p>
75	        </div>
76	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
77	          {pending ? "Saving…" : "Save & apply"}
78	        </button>
79	      </div>
80	
81	      {/* Variant / loader picker */}
82	      <div className="mt-5">
83	        <label className="block text-sm">
84	          <span className="mb-1.5 block font-medium">Server type</span>
85	          <select
86	            className="input"
87	            value={variant}
88	            disabled={pending || disabled}
89	            onChange={(e) => {
90	              setVariant(e.target.value);
91	              setSaved(false);
92	            }}
93	          >
94	            {schema.variants.map((v) => (
95	              <option key={v.id} value={v.id}>
