117	              />
118	            ))}
119	          </div>
120	        </div>
121	      ))}
122	
123	      <div className="mt-5 flex flex-wrap items-center gap-3">
124	        <button className="btn-primary" disabled={pending || disabled} onClick={save}>
125	          {pending ? "Saving…" : "Save & apply"}
126	        </button>
127	        {saved && !error && <span className="text-sm text-emerald-400">Settings queued for apply.</span>}
128	        {error && <span className="text-sm text-red-400">{error}</span>}
129	      </div>
130	    </div>
131	  );
132	}
133	
134	function Field({
135	  field,
136	  value,
137	  disabled,
138	  onChange,
139	}: {
140	  field: ConfigField;
141	  value: string | number | boolean | undefined;
142	  disabled?: boolean;
143	  onChange: (v: string | number | boolean) => void;
144	}) {
145	  const labelRow = (
146	    <span className="mb-1.5 flex items-baseline justify-between gap-2">
147	      <span className="font-medium">{field.label}</span>
148	      {field.phase === "deploy" && (
149	        <span className="text-[10px] uppercase tracking-wide text-amber-300/80">restart</span>
150	      )}
151	    </span>
152	  );
153	
154	  if (field.type === "bool") {
155	    const on = value === true;
156	    return (
157	      <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-3">
158	        <span className="text-sm">
159	          <span className="font-medium">{field.label}</span>
160	          {field.help && <span className="mt-0.5 block text-xs text-slate-500">{field.help}</span>}
161	        </span>
162	        <button
163	          type="button"
164	          role="switch"
165	          aria-checked={on}
166	          disabled={disabled}
167	          onClick={() => onChange(!on)}
168	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
169	            on ? "bg-brand-500" : "bg-white/15"
170	          } ${disabled ? "opacity-60" : ""}`}
171	        >
172	          <span
173	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
174	              on ? "translate-x-5" : "translate-x-0.5"
175	            }`}
176	          />
177	        </button>
178	      </div>
179	    );
180	  }
181	
182	  return (
183	    <label className="block text-sm">
184	      {labelRow}
185	      {field.type === "enum" ? (
186	        <select
187	          className="input"
188	          value={String(value ?? field.default)}
189	          disabled={disabled}
190	          onChange={(e) => onChange(e.target.value)}
191	        >
192	          {field.options?.map((o) => (
193	            <option key={o.value} value={o.value}>
194	              {o.label}
195	            </option>
196	          ))}
197	        </select>
198	      ) : field.type === "int" ? (
199	        <input
200	          className="input"
201	          type="number"
202	          value={value === undefined || value === null ? Number(field.default) : Number(value)}
203	          min={field.min}
204	          max={field.max}
205	          step={1}
206	          disabled={disabled}
207	          onChange={(e) => onChange(e.target.value === "" ? "" as any : Number(e.target.value))}
208	        />
209	      ) : (
210	        <input
211	          className="input"
212	          type="text"
213	          value={String(value ?? field.default)}
214	          maxLength={256}
215	          disabled={disabled}
216	          onChange={(e) => onChange(e.target.value)}
217	        />
218	      )}
219	      {field.help && (
220	        <span className="mt-1 block text-xs text-slate-500">{field.help}</span>
221	      )}
222	    </label>
223	  );
224	}
