44	async function notify(userId: string, title: string, body?: string, href?: string) {
45	  try {
46	    await db.notification.create({ data: { userId, title, body, href } });
47	  } catch (e) {
48	    console.error("[game-config] notify failed", e);
49	  }
50	}
