52	export async function gameConfigApply(job: Job): Promise<void> {
53	  const serverId = job.serverId;
54	  if (!serverId) throw new Error("game config: job has no serverId");
55	
56	  const server = await db.server.findUnique({
57	    where: { id: serverId },
58	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true },
59	  });
60	  if (!server) throw new Error(`Server ${serverId} not found`);
61	
62	  const family = familyFor(server);
63	  const schema = schemaFor(family);
64	  if (!family || !schema) {
65	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
66	  }
67	
68	  const variant = server.gameVariant ?? schema.defaultVariant;
69	
70	  // -------------------------------------------------------------------------
71	  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
72	  //
73	  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
74	  // customer request fell through to the block below, stamped an `_appliedAt`
75	  // marker, and notified them "Game settings applied on <hostname>" — with the
76	  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
77	  // customer changed their difficulty or slot count, was told it was applied, and
78	  // nothing on the server had changed.
79	  //
80	  // Identical in kind to the SSL bug fixed the same day, where production wrote a
81	  // certificate row as ACTIVE with an invented expiry while no certbot had run:
82	  // the system asserting an outcome it never performed. A change we did not apply
83	  // is a FAILURE, and it must say so loudly enough that an operator notices the
84	  // flag is missing.
85	  // -------------------------------------------------------------------------
86	  if (!REAL_APPLY_ENABLED && !SANDBOX) {
87	    throw new Error(
88	      "Game settings could not be applied: real application is switched off on this " +
89	        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
90	        "server and your settings are NOT in effect. Please contact support."
