97	      _appliedVariant: variant,
98	      _appliedAt: new Date().toISOString(),
99	      _configVersion: GAME_CONFIG_VERSION,
100	      _sandbox: SANDBOX,
101	    };
102	
103	    await db.server.update({
104	      where: { id: server.id },
105	      data: { gameConfig: { ...existing, ...marker } as any },
106	    });
