108	    await notify(
109	      server.userId,
110	      `Game settings applied on ${server.hostname}`,
111	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
112	      `/dashboard/servers/${server.id}?tab=game settings`
113	    );
114	    return;
115	  }
116	
117	  // -------------------------------------------------------------------------
118	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
119	  // a failure notifies the user but never throws out of the handler.
120	  // -------------------------------------------------------------------------
121	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
122	  const valid = validateConfig(family, existing);
123	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
124	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
