131	    const msg = e instanceof Error ? e.message : String(e);
132	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
133	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
134	  }
135	
136	  // Always record the applied-marker (even on partial/soft failure) so the portal
137	  // reflects the attempt, and note whether the real push succeeded.
138	  const marker = {
139	    _appliedVariant: variant,
140	    _appliedAt: new Date().toISOString(),
141	    _configVersion: GAME_CONFIG_VERSION,
142	    _sandbox: SANDBOX,
143	    _real: true,
144	    _realOk: outcome.ok,
145	  };
146	  try {
147	    await db.server.update({
148	      where: { id: server.id },
149	      data: { gameConfig: { ...existing, ...marker } as any },
150	    });
151	  } catch (e) {
152	    console.error("[game-config] marker update failed", e);
153	  }
154	
155	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
