157	    server.userId,
158	    outcome.ok
159	      ? `Game settings applied on ${server.hostname}`
160	      : `Game settings partially applied on ${server.hostname}`,
161	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
162	    `/dashboard/servers/${server.id}?tab=game settings`
163	  );
164	}
