167	// Real apply — per-family rendering + SSH transport
168	// ===========================================================================
169	
170	type Values = Record<string, string | number | boolean>;
171	type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };
172	
173	/** The minimal Server shape the real path needs to open an SSH connection. */
174	type SshServer = {
175	  id: string;
176	  rootPassword: string | null;
177	  rootPasswordEnc?: string | null;
178	  sshPort: number | null;
179	  dedicatedIp?: { address: string } | null;
180	};
181	
182	/**
183	 * Connect to the game-server VM (host/port derived exactly like the file manager,
184	 * user "root", password `rootPassword`), run `fn`, and always close the session.
185	 */
186	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
187	  return new Promise((resolve, reject) => {
188	    const target = connectionTarget(server as any);
189	    if (!target) {
190	      reject(new Error("server is not reachable yet — connection details are pending"));
191	      return;
192	    }
193	    const password = serverRootPassword(server);
194	    if (!password) {
195	      reject(new Error("server has no root password set"));
196	      return;
197	    }
198	
199	    const conn = new Client();
200	    let settled = false;
201	    const finish = (err: Error | null, val?: T) => {
202	      if (settled) return;
203	      settled = true;
204	      try {
205	        conn.end();
206	      } catch {
207	        /* best-effort */
208	      }
209	      if (err) reject(err);
210	      else resolve(val as T);
211	    };
212	
213	    conn.on("ready", () => {
214	      conn.sftp((err, sftp) => {
215	        if (err) return finish(err);
216	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
217	      });
218	    });
219	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
220	    conn.connect({
221	      host: target.host,
222	      port: target.port,
223	      username: "root",
224	      password,
225	      readyTimeout: CONNECT_TIMEOUT_MS,
226	    });
227	  });
228	}
229	
230	/** Read a remote text file, or null if it does not exist. */
231	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
232	  return new Promise((resolve, reject) => {
233	    sftp.readFile(path, (err, data) => {
234	      if (err) {
235	        // ENOENT / no such file → null; anything else is a real error.
236	        const code = (err as NodeJS.ErrnoException).code;
237	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
238	          return resolve(null);
239	        }
240	        return reject(err);
241	      }
242	      resolve(data.toString("utf8"));
243	    });
244	  });
245	}
246	
247	/** Write a remote text file (overwrites). */
248	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
249	  return new Promise((resolve, reject) => {
250	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
251	  });
252	}
253	
254	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
255	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
256	  return new Promise((resolve, reject) => {
257	    conn.exec(cmd, (err, stream: ClientChannel) => {
258	      if (err) return reject(err);
259	      let stdout = "";
260	      let stderr = "";
261	      const timer = setTimeout(() => {
262	        try {
263	          stream.close();
264	        } catch {
265	          /* ignore */
266	        }
267	      }, EXEC_TIMEOUT_MS);
268	      stream
269	        .on("close", (code: number) => {
270	          clearTimeout(timer);
271	          resolve({ code: code ?? 0, stdout, stderr });
272	        })
273	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
274	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
275	    });
276	  });
277	}
