279	/**
280	 * Locate the first existing path: try explicit candidates via `test -f`, then a
281	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
282	 * Non-destructive — only reads.
283	 */
284	async function remoteLocate(
285	  conn: Client,
286	  candidates: string[],
287	  findRoots: string[],
288	  findName: string
289	): Promise<string | null> {
290	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
291	  const findExpr = findRoots.length
292	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
293	    : "true";
294	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
295	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
296	  return hit ?? null;
297	}
298	
299	/** Escape a value for single-quoted shell use. */
300	function shq(s: string): string {
301	  return s.replace(/'/g, "'\\''");
302	}
