325	// key=value file helpers (server.properties)
326	// ---------------------------------------------------------------------------
327	
328	/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
329	function updateKeyValue(content: string, updates: Record<string, string>): string {
330	  const lines = content.split(/\r?\n/);
331	  const seen = new Set<string>();
332	  for (let i = 0; i < lines.length; i++) {
333	    const trimmed = lines[i].trim();
334	    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
335	    const eq = lines[i].indexOf("=");
336	    if (eq < 0) continue;
337	    const key = lines[i].slice(0, eq).trim();
338	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
339	      lines[i] = `${key}=${updates[key]}`;
340	      seen.add(key);
341	    }
342	  }
343	  for (const k of Object.keys(updates)) {
344	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
345	  }
346	  return lines.join("\n");
347	}
348	
349	/** Read a `key=value` file into a map (comments/blank lines ignored). */
350	function parseKeyValue(content: string): Record<string, string> {
351	  const out: Record<string, string> = {};
352	  for (const line of content.split(/\r?\n/)) {
353	    const t = line.trim();
354	    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
355	    const eq = line.indexOf("=");
356	    if (eq < 0) continue;
357	    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
358	  }
359	  return out;
360	}
