392	async function applyMinecraft(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
393	  // TODO(paths): confirm the actual install dir/service name for the Minecraft
394	  // image. These candidates cover the common layouts; if none match we soft-fail
395	  // rather than create a stray server.properties in the wrong place.
396	  const path = await remoteLocate(
397	    conn,
398	    [
399	      "/opt/minecraft/server.properties",
400	      "/srv/minecraft/server.properties",
401	      "/home/minecraft/server.properties",
402	      "/minecraft/server.properties",
403	      "/root/minecraft/server.properties",
404	    ],
405	    ["/opt", "/srv", "/home"],
406	    "server.properties"
407	  );
408	  if (!path) {
409	    return { ok: false, applied: [], notes: ["Could not locate server.properties — nothing was changed (restart/redeploy needed once the config path is known)."] };
410	  }
411	
412	  const existing = await sftpRead(sftp, path);
413	  if (existing == null) {
414	    return { ok: false, applied: [], notes: [`server.properties disappeared at ${path} — nothing was changed.`] };
415	  }
416	
417	  // server.properties keys map 1:1 to the schema field keys.
418	  const updates: Record<string, string> = {};
419	  for (const [key, val] of Object.entries(v)) {
420	    updates[key] = typeof val === "boolean" ? bool(val) : String(val);
421	  }
422	  const next = updateKeyValue(existing, updates);
423	  await sftpWrite(sftp, path, next);
424	
425	  const notes: string[] = [];
426	  // Best-effort live push via RCON for the live-editable fields; otherwise note a
427	  // restart. Wrapped so RCON problems never fail the apply.
428	  try {
429	    await tryMinecraftRcon(conn, next, v, notes);
430	  } catch (e) {
431	    notes.push("RCON push skipped (unavailable). A restart is required for changes to take effect.");
432	    console.error("[game-config] minecraft rcon error", e);
433	  }
434	
435	  return {
436	    ok: true,
437	    applied: [`Wrote ${Object.keys(updates).length} setting(s) to ${path}.`],
438	    notes: notes.length ? notes : ["Restart the server for deploy-time settings (hardcore, online-mode) to take effect."],
439	  };
