442	/**
443	 * Best-effort Minecraft RCON push. Reads rcon config from the (updated)
444	 * server.properties; if RCON is enabled, a password is set, and `mcrcon` exists
445	 * on the box, pushes the live-editable settings. Anything missing → note a restart.
446	 */
447	async function tryMinecraftRcon(conn: Client, props: string, v: Values, notes: string[]): Promise<void> {
448	  const kv = parseKeyValue(props);
449	  const enabled = kv["enable-rcon"] === "true";
450	  const password = kv["rcon.password"] ?? "";
451	  // `rcon.port` is read out of the CUSTOMER'S OWN server.properties, on the
452	  // customer's own VM — an attacker-controlled string in every sense, and one
453	  // this platform never wrote. Only a TCP port number can ever be legitimate, so
454	  // anything that is not one is discarded rather than escaped. `shq` and the
455	  // quoting below are the second and third lines of defence; this is the first,
456	  // and it is the only one that does not depend on getting quoting right.
457	  const port = rconPort(kv["rcon.port"]);
458	  if (!enabled || !password) {
459	    notes.push("RCON is not enabled — restart the server to apply the new settings live.");
460	    return;
461	  }
462	  const which = await execRemote(conn, "command -v mcrcon || true");
463	  if (!which.stdout.trim()) {
464	    notes.push("RCON is enabled but `mcrcon` is not installed — restart to apply live.");
465	    return;
466	  }
467	
468	  // A conservative set of safe live commands. TODO(rcon): expand once the exact
469	  // runtime command set is verified for the target Minecraft build.
470	  const cmds: string[] = [];
471	  if (v["difficulty"] != null) cmds.push(`difficulty ${String(v["difficulty"])}`);
472	  if (v["white-list"] != null) cmds.push(`whitelist ${bool(v["white-list"]) === "true" ? "on" : "off"}`);
473	  if (v["pvp"] != null || v["max-players"] != null || v["motd"] != null) cmds.push("reload");
474	  if (cmds.length === 0) return;
475	
476	  const quoted = cmds.map((c) => `'${shq(c)}'`).join(" ");
477	  // EVERY interpolation is inside single quotes. `shq` escapes a value for use
478	  // INSIDE a single-quoted string — it is not a quoter, and a bare `${shq(x)}`
479	  // is simply an unquoted, word-splitting, metacharacter-honouring shell
480	  // argument. `-P` was written that way, so `rcon.port=1; curl … | sh` in the
481	  // customer's own server.properties ran as root on the hypervisor's SSH client
482	  // target with no further steps required.
483	  //
484	  // The `|| true` that used to end this line is gone. It forced exit 0, so the
485	  // `res.code === 0` test below was a constant and this function reported
486	  // "Pushed live settings via RCON." whether mcrcon worked, refused the
487	  // password, or was never reached. `execRemote` resolves with the real exit
488	  // code rather than rejecting, so nothing here can throw on a non-zero status —
489	  // the note just becomes true.
490	  const res = await execRemote(
491	    conn,
492	    `mcrcon -H 127.0.0.1 -P '${shq(port)}' -p '${shq(password)}' ${quoted} 2>&1`
493	  );
494	  notes.push(res.code === 0 ? "Pushed live settings via RCON." : "RCON push attempted (some settings may need a restart).");
495	}
