497	/**
498	 * The RCON port to talk to, from an untrusted `rcon.port` value.
499	 *
500	 * Accepts only a bare 1–65535 decimal; anything else (empty, non-numeric, out of
501	 * range, or carrying a shell payload) falls back to Minecraft's default 25575.
502	 * Returns a string because it is interpolated into a command line, and returning
503	 * the parsed digits — never the caller's original text — is what makes the value
504	 * safe by construction rather than by escaping.
505	 */
506	function rconPort(raw: string | undefined): string {
507	  const n = Number(String(raw ?? "").trim());
508	  if (!Number.isInteger(n) || n < 1 || n > 65535) return "25575";
509	  return String(n);
510	}
