663	// ---------------------------------------------------------------------------
664	
665	/** Split a comma-separated OptionSettings body at top level (respecting quotes). */
666	function splitTopLevel(s: string): string[] {
667	  const out: string[] = [];
668	  let cur = "";
669	  let inQuote = false;
670	  for (const ch of s) {
671	    if (ch === '"') inQuote = !inQuote;
672	    if (ch === "," && !inQuote) {
673	      out.push(cur);
674	      cur = "";
675	    } else {
676	      cur += ch;
677	    }
678	  }
679	  if (cur.length) out.push(cur);
680	  return out;
681	}
682	
683	/**
684	 * Update keys inside the `OptionSettings=(...)` block, preserving the section
685	 * header, all other keys, and quoting. Returns null if the block can't be parsed
686	 * (so the caller soft-fails instead of clobbering the file).
687	 */
688	function updatePalworld(content: string, updates: Record<string, string>): string | null {
689	  const idx = content.indexOf("OptionSettings=(");
690	  if (idx < 0) return null;
691	  const open = content.indexOf("(", idx);
692	  const close = content.indexOf(")", open);
693	  if (open < 0 || close < 0) return null;
694	
695	  const inner = content.slice(open + 1, close);
696	  const pairs = splitTopLevel(inner);
697	  const order: string[] = [];
698	  const map = new Map<string, string>();
699	  for (const p of pairs) {
700	    const eq = p.indexOf("=");
701	    if (eq < 0) continue;
702	    const k = p.slice(0, eq).trim();
703	    order.push(k);
704	    map.set(k, p.slice(eq + 1));
705	  }
706	  for (const [k, val] of Object.entries(updates)) {
707	    if (!map.has(k)) order.push(k);
708	    map.set(k, val);
709	  }
710	  const rebuilt = order.map((k) => `${k}=${map.get(k)}`).join(",");
711	  return content.slice(0, open + 1) + rebuilt + content.slice(close);
712	}
