738	  if (v["pvp"] != null) updates["bEnablePlayerToPlayerDamage"] = bool(v["pvp"]) === "true" ? "True" : "False";
739	  if (v["exp-rate"] != null) {
740	    const n = Number(v["exp-rate"]);
741	    updates["ExpRate"] = Number.isFinite(n) ? n.toFixed(6) : String(v["exp-rate"]);
742	  }
743	  if (v["player-caps"] != null) updates["ServerPlayerMaxNum"] = String(v["player-caps"]);
744	
745	  const next = updatePalworld(existing, updates);
746	  if (next == null) {
747	    return {
748	      ok: false,
749	      applied: [],
750	      notes: [`Could not parse the OptionSettings line in ${path} — left untouched to avoid corrupting it.`],
751	    };
752	  }
753	  await sftpWrite(sftp, path, next);
754	
755	  // Palworld has no live-editable path for these — a restart is always required.
756	  return {
757	    ok: true,
758	    applied: [`Updated ${Object.keys(updates).length} setting(s) in ${path}.`],
759	    notes: ["Restart the Palworld server for the new settings to take effect."],
760	  };
761	}
