61	/** Strip any existing Nxeon-managed block from an existing crontab body. */
62	function stripManaged(current: string): string {
63	  const lines = current.split("\n");
64	  const out: string[] = [];
65	  let inBlock = false;
66	  for (const line of lines) {
67	    if (line.trim() === BEGIN) {
68	      inBlock = true;
69	      continue;
70	    }
71	    if (line.trim() === END) {
72	      inBlock = false;
73	      continue;
74	    }
75	    if (!inBlock) out.push(line);
76	  }
77	  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd();
78	}
