/**
 * Game server control panel — SSH/RCON transport + per-family control facts.
 *
 * A plain server-side module (NO "use server", no client imports). Imported by
 * BOTH the server actions (lib/actions-game-control.ts) and the worker
 * (worker/game-control.ts). It NEVER runs in the browser — the customer's root
 * credentials and their server's RCON password stay on our server.
 *
 * Everything here operates on the CUSTOMER'S OWN game VM over the platform's
 * existing SSH (host/port/root-password derived exactly like lib/sftp.ts, reused
 * via lib/ssh-exec.ts `withServerSsh`). Two transport rules, mirroring the rest of
 * the control panel:
 *
 *   1. STRICT ALLOWLIST VALIDATION for anything that reaches a shell. Ports, unit
 *      names, paths and file names are validated/allowlisted or rejected — never
 *      sanitized. Family/unit hints are compile-time constants, never customer
 *      input.
 *
 *   2. RCON never touches a shell at all. We read the server's RCON port/password
 *      out of its own config file, then open a TCP channel to 127.0.0.1:<port> on
 *      the game VM THROUGH the SSH connection (`conn.forwardOut`) and speak the
 *      Source RCON wire protocol directly. The RCON port is never exposed off the
 *      box, the password is only ever a protocol packet body (not an argv token),
 *      and the customer's console command is validated to be single-line/control-
 *      char-free before it is sent.
 *
 * SANDBOX: callers gate real SSH behind `!SANDBOX`; on staging the inline reads
 * return realistic synthetic data so the whole UX works without a live VM.
 */
import type { Duplex } from "node:stream";
import type { Client } from "ssh2";
import { GAME_FAMILIES, type GameFamily } from "./games";
import { exec, QUICK_TIMEOUT_MS } from "./ssh-exec";

// ---------------------------------------------------------------------------
// Per-family control facts
// ---------------------------------------------------------------------------

/** How (if at all) we can talk to a running server's console remotely. */
export type RconProtocol =
  | "source" // Valve Source RCON (Minecraft, CS2, Palworld) — implemented here
  | "rust-web" // Rust WebSocket RCON — different protocol, deferred
  | "none"; // no remote console protocol (Valheim/Terraria vanilla)

/** Where a family stores the RCON credentials, and how to parse that file. */
type RconConfig = {
  /** Config-file path candidates to try first (absolute). */
  candidates: string[];
  /** Roots to bounded-`find` under if none of the candidates exist. */
  findRoots: string[];
  /** File name to find. */
  findName: string;
  /** File format. */
  kind: "properties" | "palworld-ini";
  /** Key that gates RCON being on (value compared case-insensitively to true/1). */
  enableKey?: string;
  /** Key holding the RCON password. */
  passwordKey: string;
  /** Key holding the RCON port (falls back to `defaultPort`). */
  portKey?: string;
  /** Port used when the file does not specify one. */
  defaultPort: number;
};

export type GameControlSpec = {
  family: GameFamily;
  label: string;
  /** systemd unit-name hints (first that resolves wins). Compile-time constants. */
  serviceHints: string[];
  /** Directory candidates that hold the world/save data (for listing + backup). */
  dataRoots: string[];
  /** Remote console protocol. */
  rcon: RconProtocol;
  /** Where/how to read RCON creds (present only when rcon === "source"). */
  rconConfig?: RconConfig;
  /** RCON verb that lists connected players (present when supported). */
  listCommand?: string;
  /** RCON verb template for kicking a player (`%s` = validated name/id). */
  kickCommand?: string;
  /** RCON verb template for banning a player (`%s` = validated name/id). */
  banCommand?: string;
};

/**
 * The control facts per game family.
 *
 * RCON reality (why not every "has RCON" game gets a wire here):
 *  - minecraft: native Source RCON (enable-rcon / rcon.password / rcon.port).
 *  - cs2:       native Source RCON (rcon_password; port defaults to the game port).
 *  - palworld:  native RCON, Source-protocol framing (RCONEnabled/RCONPort/AdminPassword).
 *  - rust:      RCON is WebSocket (rcon.web) — a DIFFERENT protocol; deferred.
 *  - valheim:   no native RCON (needs a BepInEx mod) — console disabled.
 *  - terraria:  vanilla has only a local stdin console — console disabled.
 */
export const GAME_CONTROL: Record<GameFamily, GameControlSpec> = {
  minecraft: {
    family: "minecraft",
    label: "Minecraft",
    serviceHints: ["minecraft", "minecraft-server"],
    dataRoots: ["/opt/minecraft", "/srv/minecraft", "/home/minecraft", "/root/minecraft", "/minecraft"],
    rcon: "source",
    rconConfig: {
      candidates: [
        "/opt/minecraft/server.properties",
        "/srv/minecraft/server.properties",
        "/home/minecraft/server.properties",
        "/root/minecraft/server.properties",
      ],
      findRoots: ["/opt", "/srv", "/home"],
      findName: "server.properties",
      kind: "properties",
      enableKey: "enable-rcon",
      passwordKey: "rcon.password",
      portKey: "rcon.port",
      defaultPort: 25575,
    },
    listCommand: "list",
    kickCommand: "kick %s",
    banCommand: "ban %s",
  },
  cs2: {
    family: "cs2",
    label: "Counter-Strike 2",
    serviceHints: ["cs2", "cs2-server"],
    dataRoots: ["/opt/cs2", "/home/cs2", "/home/steam/cs2"],
    rcon: "source",
    rconConfig: {
      candidates: [
        "/opt/cs2/game/csgo/cfg/server.cfg",
        "/home/cs2/cs2/game/csgo/cfg/server.cfg",
        "/home/steam/cs2/game/csgo/cfg/server.cfg",
      ],
      findRoots: ["/opt/cs2", "/home/cs2", "/home/steam"],
      findName: "server.cfg",
      kind: "properties",
      // CS2 server.cfg uses `key value`; our reader also accepts `key=value`.
      passwordKey: "rcon_password",
      defaultPort: 27015,
    },
    listCommand: "status",
    kickCommand: "kick %s",
    banCommand: "banid 0 %s",
  },
  palworld: {
    family: "palworld",
    label: "Palworld",
    serviceHints: ["palworld", "palworld-server", "palserver"],
    dataRoots: [
      "/opt/palworld/Pal/Saved/SaveGames",
      "/home/steam/Steam/steamapps/common/PalServer/Pal/Saved/SaveGames",
      "/home/palworld/Pal/Saved/SaveGames",
    ],
    rcon: "source",
    rconConfig: {
      candidates: [
        "/opt/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
        "/home/steam/Steam/steamapps/common/PalServer/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
        "/home/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini",
      ],
      findRoots: ["/opt/palworld", "/home/steam", "/home/palworld"],
      findName: "PalWorldSettings.ini",
      kind: "palworld-ini",
      enableKey: "RCONEnabled",
      passwordKey: "AdminPassword",
      portKey: "RCONPort",
      defaultPort: 25575,
    },
    listCommand: "ShowPlayers",
    kickCommand: "KickPlayer %s",
    banCommand: "BanPlayer %s",
  },
  rust: {
    family: "rust",
    label: "Rust",
    serviceHints: ["rust", "rust-server", "rustserver"],
    dataRoots: ["/opt/rust/server", "/home/rust/server", "/home/steam/rust"],
    rcon: "rust-web", // WebSocket RCON — deferred (see sendRcon)
  },
  valheim: {
    family: "valheim",
    label: "Valheim",
    serviceHints: ["valheim", "valheim-server"],
    dataRoots: [
      "/root/.config/unity3d/IronGate/Valheim/worlds_local",
      "/home/valheim/.config/unity3d/IronGate/Valheim/worlds_local",
      "/opt/valheim/worlds_local",
    ],
    rcon: "none", // no native RCON
  },
  terraria: {
    family: "terraria",
    label: "Terraria",
    serviceHints: ["terraria", "terraria-server"],
    dataRoots: ["/opt/terraria/worlds", "/root/.local/share/Terraria/Worlds", "/home/terraria/worlds"],
    rcon: "none", // vanilla: local stdin console only
  },
};

export function controlSpec(family: string | null | undefined): GameControlSpec | null {
  if (!family) return null;
  return (GAME_CONTROL as Record<string, GameControlSpec>)[family] ?? null;
}

export function isGameFamily(family: string | null | undefined): family is GameFamily {
  return !!family && (GAME_FAMILIES as readonly string[]).includes(family);
}

// ---------------------------------------------------------------------------
// Validation helpers (reject, never sanitize)
// ---------------------------------------------------------------------------

/** Actions the customer can take on the game SERVICE. */
export const GAME_POWER_ACTIONS = ["start", "stop", "restart"] as const;
export type GamePowerAction = (typeof GAME_POWER_ACTIONS)[number];

export function isPowerAction(a: string): a is GamePowerAction {
  return (GAME_POWER_ACTIONS as readonly string[]).includes(a);
}

/**
 * A TCP port from an UNTRUSTED source (the customer's own config file, or a form).
 * Returns a 1..65535 integer or null — the parsed number, never the caller's text,
 * so it is safe by construction rather than by escaping.
 */
export function parsePort(raw: unknown): number | null {
  const n = Number(String(raw ?? "").trim());
  if (!Number.isInteger(n) || n < 1 || n > 65535) return null;
  return n;
}

/**
 * A single RCON/console command line typed by the customer. Their own server, so
 * the verb set is intentionally open — but it is sent as a Source RCON packet body
 * (never a shell), and we still forbid NUL/newline/control chars (which would forge
 * multiple packets or corrupt framing) and bound the length.
 */
export function validateRconCommand(raw: string): { ok: true; command: string } | { ok: false; error: string } {
  const c = String(raw ?? "");
  if (c.trim().length === 0) return { ok: false, error: "Enter a command." };
  if (c.length > 512) return { ok: false, error: "Command is too long (max 512 chars)." };
  // eslint-disable-next-line no-control-regex
  if (/[\x00-\x1f\x7f]/.test(c)) return { ok: false, error: "Command may not contain line breaks or control characters." };
  return { ok: true, command: c.trim() };
}

/**
 * A player identifier (name / SteamID / UID) used to build a kick/ban command.
 * Restricted to a shell-and-protocol-inert token so it can be interpolated into an
 * RCON verb template with no framing or word-splitting surprises.
 */
export function validatePlayerId(raw: string): { ok: true; id: string } | { ok: false; error: string } {
  const id = String(raw ?? "").trim();
  if (!/^[A-Za-z0-9_.:-]{1,64}$/.test(id)) return { ok: false, error: "Unsupported player identifier." };
  return { ok: true, id };
}

/** Absolute path allowlist for a located config/data path (no traversal). */
const SAFE_PATH_RE = /^\/[A-Za-z0-9._/ -]{1,255}$/;
export function isSafeRemotePath(p: string): boolean {
  return typeof p === "string" && SAFE_PATH_RE.test(p) && !p.includes("..") && !p.includes("//");
}

/** Defensive POSIX single-quote (values are also allowlisted before reaching here). */
export function shq(s: string): string {
  return `'${String(s).replace(/'/g, `'\\''`)}'`;
}

// ---------------------------------------------------------------------------
// Remote locate + config read (read-only, over the shared SSH `exec`)
// ---------------------------------------------------------------------------

/**
 * Locate the first existing file: explicit candidates via `test -f`, then a
 * bounded `find` over `roots`. Candidate paths are compile-time constants; the
 * returned hit is re-validated against the path allowlist before any caller uses
 * it. Returns null when nothing matches.
 */
export async function remoteLocateFile(
  conn: Client,
  candidates: string[],
  roots: string[],
  name: string
): Promise<string | null> {
  const testExpr = candidates.map((p) => `if [ -f ${shq(p)} ]; then echo ${shq(p)}; exit 0; fi;`).join(" ");
  const findExpr = roots.length
    ? `for r in ${roots.map((r) => shq(r)).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name ${shq(name)} 2>/dev/null | head -1; done | head -1`
    : "true";
  const { stdout } = await exec(conn, `${testExpr} ${findExpr}`, QUICK_TIMEOUT_MS);
  const hit = stdout
    .split(/\r?\n/)
    .map((s) => s.trim())
    .find((s) => s.length > 0);
  return hit && isSafeRemotePath(hit) ? hit : null;
}

/** Locate the first existing directory from a candidate list. */
export async function remoteLocateDir(conn: Client, candidates: string[]): Promise<string | null> {
  const expr = candidates.map((p) => `if [ -d ${shq(p)} ]; then echo ${shq(p)}; exit 0; fi;`).join(" ");
  const { stdout } = await exec(conn, expr, QUICK_TIMEOUT_MS);
  const hit = stdout
    .split(/\r?\n/)
    .map((s) => s.trim())
    .find((s) => s.length > 0);
  return hit && isSafeRemotePath(hit) ? hit : null;
}

/** Read a small remote text file (or null). Uses `cat`, capped by head. */
async function readRemoteText(conn: Client, path: string): Promise<string | null> {
  if (!isSafeRemotePath(path)) return null;
  const { stdout, code } = await exec(conn, `cat ${shq(path)} 2>/dev/null | head -c 65536`, QUICK_TIMEOUT_MS);
  if (code !== 0 && stdout.length === 0) return null;
  return stdout;
}

/** Parse a `key=value` / `key value` config into a lowercase-keyed map. */
function parseFlatConfig(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of text.split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#") || t.startsWith("//") || t.startsWith("!") || t.startsWith(";")) continue;
    let key: string;
    let val: string;
    const eq = t.indexOf("=");
    if (eq >= 0) {
      key = t.slice(0, eq).trim();
      val = t.slice(eq + 1).trim();
    } else {
      const sp = t.search(/\s/);
      if (sp < 0) continue;
      key = t.slice(0, sp).trim();
      val = t.slice(sp + 1).trim();
    }
    // Strip surrounding quotes.
    val = val.replace(/^"(.*)"$/, "$1").replace(/^'(.*)'$/, "$1");
    if (key) out[key.toLowerCase()] = val;
  }
  return out;
}

/** Pull `Key=Value` pairs out of Palworld's `OptionSettings=(...)` blob. */
function parsePalworldIni(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  const idx = text.indexOf("OptionSettings=(");
  const open = idx >= 0 ? text.indexOf("(", idx) : -1;
  const close = open >= 0 ? text.indexOf(")", open) : -1;
  if (open < 0 || close < 0) return out;
  const inner = text.slice(open + 1, close);
  let cur = "";
  let inQuote = false;
  const pairs: string[] = [];
  for (const ch of inner) {
    if (ch === '"') inQuote = !inQuote;
    if (ch === "," && !inQuote) {
      pairs.push(cur);
      cur = "";
    } else cur += ch;
  }
  if (cur) pairs.push(cur);
  for (const p of pairs) {
    const eq = p.indexOf("=");
    if (eq < 0) continue;
    let v = p.slice(eq + 1).trim();
    v = v.replace(/^"(.*)"$/, "$1");
    out[p.slice(0, eq).trim().toLowerCase()] = v;
  }
  return out;
}

export type RconCreds =
  | { ok: true; port: number; password: string }
  | { ok: false; reason: string };

/**
 * Read a game server's RCON credentials out of its own config file, over SSH.
 * The password is used ONLY as a Source RCON packet body downstream — never a
 * shell argument — and the port is parsed to an integer (`parsePort`), so neither
 * value can inject anywhere.
 */
export async function readRconCreds(conn: Client, spec: GameControlSpec): Promise<RconCreds> {
  const cfg = spec.rconConfig;
  if (spec.rcon !== "source" || !cfg) {
    return { ok: false, reason: `Remote console is not available for ${spec.label}.` };
  }
  const path = await remoteLocateFile(conn, cfg.candidates, cfg.findRoots, cfg.findName);
  if (!path) return { ok: false, reason: `Could not find ${spec.label}'s config file to read RCON settings.` };
  const text = await readRemoteText(conn, path);
  if (text == null) return { ok: false, reason: `Could not read ${spec.label}'s config file.` };

  const map = cfg.kind === "palworld-ini" ? parsePalworldIni(text) : parseFlatConfig(text);

  if (cfg.enableKey) {
    const en = (map[cfg.enableKey.toLowerCase()] ?? "").toLowerCase();
    if (en !== "true" && en !== "1" && en !== "on") {
      return { ok: false, reason: `RCON is not enabled in ${spec.label}'s config — enable it and restart to use the console.` };
    }
  }
  const password = map[cfg.passwordKey.toLowerCase()] ?? "";
  if (!password) return { ok: false, reason: `No RCON password is set in ${spec.label}'s config.` };
  if (password.length > 256) return { ok: false, reason: "RCON password in the config looks malformed." };

  const port = cfg.portKey ? parsePort(map[cfg.portKey.toLowerCase()]) ?? cfg.defaultPort : cfg.defaultPort;
  return { ok: true, port, password };
}

// ---------------------------------------------------------------------------
// Source RCON over an SSH-forwarded TCP channel
// ---------------------------------------------------------------------------

const RCON_TYPE_AUTH = 3;
const RCON_TYPE_EXEC = 2;
const RCON_TYPE_RESPONSE = 0;
const RCON_ID_AUTH = 0x1;
const RCON_ID_CMD = 0x2;
const RCON_ID_END = 0x2711; // sentinel id for the trailing empty packet

function rconPacket(id: number, type: number, body: string): Buffer {
  const bodyBuf = Buffer.from(body, "ascii");
  const buf = Buffer.alloc(bodyBuf.length + 14);
  buf.writeInt32LE(bodyBuf.length + 10, 0); // size = id(4)+type(4)+body+2 nulls
  buf.writeInt32LE(id, 4);
  buf.writeInt32LE(type, 8);
  bodyBuf.copy(buf, 12);
  // two trailing NUL bytes already zero from Buffer.alloc
  return buf;
}

/**
 * Open a TCP channel to `host:port` on the game VM THROUGH the authenticated SSH
 * connection. The RCON port therefore never needs to be reachable off the box.
 */
export function forwardTcp(conn: Client, host: string, port: number, timeoutMs = 8000): Promise<Duplex> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("Timed out opening RCON channel")), timeoutMs);
    conn.forwardOut("127.0.0.1", 0, host, port, (err, stream) => {
      clearTimeout(timer);
      if (err) return reject(err);
      resolve(stream as unknown as Duplex);
    });
  });
}

export type RconResult = { ok: true; response: string } | { ok: false; error: string };

/**
 * Speak Source RCON over `stream`: authenticate, run `command`, and read the
 * (possibly multi-packet) response, using a trailing empty packet as the
 * end-of-response sentinel. Never throws — resolves an {ok,error} result. The
 * password is only ever a packet body; the command was validated by the caller.
 */
export function sourceRcon(stream: Duplex, password: string, command: string, timeoutMs = 8000): Promise<RconResult> {
  return new Promise((resolve) => {
    let acc = Buffer.alloc(0);
    let authed = false;
    let response = "";
    let done = false;

    const finish = (r: RconResult) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      try {
        stream.end();
      } catch {
        /* best effort */
      }
      resolve(r);
    };
    const timer = setTimeout(
      () => finish(authed ? { ok: true, response } : { ok: false, error: "RCON timed out (no response)." }),
      timeoutMs
    );

    stream.on("data", (chunk: Buffer) => {
      acc = Buffer.concat([acc, chunk]);
      while (acc.length >= 4) {
        const size = acc.readInt32LE(0);
        if (size < 10 || size > 4110) return finish({ ok: false, error: "Malformed RCON response." });
        if (acc.length < size + 4) break;
        const id = acc.readInt32LE(4);
        const type = acc.readInt32LE(8);
        const body = acc.slice(12, 4 + size - 2).toString("ascii");
        acc = acc.slice(4 + size);

        if (!authed) {
          // The auth response is a type-2 (AUTH_RESPONSE) packet; id === -1 on failure.
          if (type === RCON_TYPE_EXEC) {
            if (id === -1) return finish({ ok: false, error: "RCON authentication failed (wrong password)." });
            authed = true;
            stream.write(rconPacket(RCON_ID_CMD, RCON_TYPE_EXEC, command));
            stream.write(rconPacket(RCON_ID_END, RCON_TYPE_EXEC, "")); // sentinel
          }
          // A leading empty RESPONSE_VALUE some servers send pre-auth is ignored.
        } else {
          if (id === RCON_ID_END) return finish({ ok: true, response });
          if (type === RCON_TYPE_RESPONSE) response += body;
        }
      }
    });
    stream.on("error", (e: Error) => finish({ ok: false, error: e?.message || "RCON connection error." }));
    stream.on("close", () => finish(authed ? { ok: true, response } : { ok: false, error: "RCON connection closed." }));

    stream.write(rconPacket(RCON_ID_AUTH, RCON_TYPE_AUTH, password));
  });
}

/**
 * Full inline RCON round-trip on an already-open SSH connection: read creds from
 * the server's config, tunnel to 127.0.0.1:<port>, run one command. Callers guard
 * SANDBOX and ownership before reaching here.
 */
export async function runRcon(conn: Client, spec: GameControlSpec, command: string): Promise<RconResult> {
  const creds = await readRconCreds(conn, spec);
  if (!creds.ok) return { ok: false, error: creds.reason };
  let stream: Duplex;
  try {
    stream = await forwardTcp(conn, "127.0.0.1", creds.port);
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : "Could not open RCON channel." };
  }
  return sourceRcon(stream, creds.password, command);
}

// ---------------------------------------------------------------------------
// Log / world / backup readers (read-only shell over the shared `exec`)
// ---------------------------------------------------------------------------

/** Directory the platform writes game world backups to (fixed, never user input). */
export const GAME_BACKUP_DIR = "/var/backups/nxeon-game";

export type LogResult = { ok: true; lines: string[]; unit: string | null } | { ok: false; error: string };

/**
 * Tail the game service's recent logs. Resolves the unit from the family hints
 * (compile-time constants), then reads the last `n` journal lines; if journald has
 * nothing, falls back to a `.log` file under the data roots. Read-only.
 */
export async function readGameLogs(conn: Client, spec: GameControlSpec, n = 200): Promise<LogResult> {
  const lines = Math.min(Math.max(Math.trunc(n) || 200, 20), 500);
  const hints = spec.serviceHints.map(shq).join(" ");
  const roots = spec.dataRoots.map(shq).join(" ");
  const script = [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `echo "NXLOG:UNIT:${"$"}{unit:-none}"`,
    `if [ -n "$unit" ]; then journalctl -u "$unit" -n ${lines} --no-pager 2>/dev/null; fi`,
    // Fallback: newest *.log under the data roots (bounded).
    `f=""; for r in ${roots}; do [ -d "$r" ] && f=$(find "$r" -maxdepth 4 -type f -name '*.log' 2>/dev/null | head -1) && [ -n "$f" ] && break; done`,
    `if [ -n "$f" ]; then echo "NXLOG:FILE:$f"; tail -n ${lines} "$f" 2>/dev/null; fi`,
  ].join("\n");
  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
  const all = stdout.split(/\r?\n/);
  let unit: string | null = null;
  const out: string[] = [];
  for (const l of all) {
    const m = /^NXLOG:UNIT:(.*)$/.exec(l);
    if (m) {
      unit = m[1] === "none" ? null : m[1];
      continue;
    }
    if (/^NXLOG:FILE:/.test(l)) continue;
    out.push(l);
  }
  while (out.length && out[out.length - 1].trim() === "") out.pop();
  return { ok: true, lines: out.slice(-lines), unit };
}

export type WorldEntry = { name: string; sizeBytes: number; isDir: boolean };
export type WorldResult = { ok: true; dir: string | null; entries: WorldEntry[] } | { ok: false; error: string };

/** List the top-level world/save entries with sizes. Read-only. */
export async function readWorlds(conn: Client, spec: GameControlSpec): Promise<WorldResult> {
  const dir = await remoteLocateDir(conn, spec.dataRoots);
  if (!dir) return { ok: true, dir: null, entries: [] };
  // `du -sb` on each top-level entry: size<TAB>path. Bounded to 200 entries.
  const script =
    `cd ${shq(dir)} 2>/dev/null || exit 0; ` +
    `for e in * .*; do [ "$e" = "." ] || [ "$e" = ".." ] && continue; [ -e "$e" ] || continue; ` +
    `t=f; [ -d "$e" ] && t=d; sz=$(du -sb "$e" 2>/dev/null | cut -f1); echo "$t\t${"$"}{sz:-0}\t$e"; done | head -200`;
  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
  const entries: WorldEntry[] = [];
  for (const line of stdout.split(/\r?\n/)) {
    const parts = line.split("\t");
    if (parts.length < 3) continue;
    const [t, sz, ...rest] = parts;
    const name = rest.join("\t").trim();
    if (!name) continue;
    entries.push({ name, sizeBytes: Number(sz) || 0, isDir: t === "d" });
  }
  return { ok: true, dir, entries };
}

export type BackupEntry = { name: string; path: string; sizeBytes: number; modifiedMs: number };
export type BackupListResult = { ok: true; backups: BackupEntry[] } | { ok: false; error: string };

/** List existing world backup archives the platform has created. Read-only. */
export async function readGameBackups(conn: Client): Promise<BackupListResult> {
  const script =
    `d=${shq(GAME_BACKUP_DIR)}; [ -d "$d" ] || exit 0; ` +
    `for f in "$d"/*.tar.gz; do [ -f "$f" ] || continue; ` +
    `sz=$(stat -c '%s' "$f" 2>/dev/null); mt=$(stat -c '%Y' "$f" 2>/dev/null); ` +
    `echo "${"$"}{sz:-0}\t${"$"}{mt:-0}\t$f"; done | head -100`;
  const { stdout } = await exec(conn, script, QUICK_TIMEOUT_MS);
  const backups: BackupEntry[] = [];
  for (const line of stdout.split(/\r?\n/)) {
    const parts = line.split("\t");
    if (parts.length < 3) continue;
    const path = parts.slice(2).join("\t").trim();
    if (!path || !isSafeRemotePath(path)) continue;
    backups.push({
      name: path.split("/").pop() || path,
      path,
      sizeBytes: Number(parts[0]) || 0,
      modifiedMs: (Number(parts[1]) || 0) * 1000,
    });
  }
  backups.sort((a, b) => b.modifiedMs - a.modifiedMs);
  return { ok: true, backups };
}

// ---------------------------------------------------------------------------
// Player-list parsing (from RCON responses)
// ---------------------------------------------------------------------------

export type Player = { name: string; extra?: string };

/**
 * Parse the connected-player list out of a family's list-command RCON response.
 * Best-effort per family; unknown shapes return the raw response so the UI can
 * still show it.
 */
export function parsePlayers(family: GameFamily, response: string): { players: Player[]; raw: string } {
  const raw = response.trim();
  if (family === "minecraft") {
    // "There are 2 of a max of 20 players online: Alice, Bob"
    const m = /players online:\s*(.*)$/i.exec(raw);
    const names = m && m[1].trim() ? m[1].split(",").map((s) => s.trim()).filter(Boolean) : [];
    return { players: names.map((name) => ({ name })), raw };
  }
  if (family === "palworld") {
    // "name,playeruid,steamid" lines, first line is a header.
    const lines = raw.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    const players: Player[] = [];
    for (const l of lines) {
      if (/^name\s*,/i.test(l)) continue;
      const cols = l.split(",");
      if (cols[0]) players.push({ name: cols[0].trim(), extra: cols.slice(1).join(",").trim() || undefined });
    }
    return { players, raw };
  }
  // cs2 `status` and anything else: hand back the raw block.
  return { players: [], raw };
}

"use server";

/**
 * Game server control panel — server actions ("Manage" tab).
 *
 * Ownership-guarded (owner or admin), rate-limited wrappers around:
 *   - Power: start/stop/restart the game SERVICE (GAME_POWER job → worker).
 *   - Live console: tail logs (inline SSH read) + send an RCON/console command
 *     (inline SSH → SSH-tunnelled Source RCON, lib/game-control.ts).
 *   - Players: list + kick/ban over RCON (where the family supports it).
 *   - World/saves: list save entries, create a downloadable backup (GAME_BACKUP
 *     job), list existing backups (download via /api/files).
 *   - Scheduled restarts: CRUD over GameSchedule; the worker sweep fires them.
 *
 * Every value that reaches a shell/RCON is validated in lib/game-control.ts
 * (ports, paths, player ids, command lines). Root/RCON credentials never leave the
 * server and are never surfaced in an error. SANDBOX: inline reads return realistic
 * synthetic data; mutating jobs settle without touching a VM.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { SANDBOX } from "./sandbox";
import { withServerSsh } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import {
  controlSpec,
  isGameFamily,
  isPowerAction,
  validateRconCommand,
  validatePlayerId,
  readGameLogs,
  readWorlds,
  readGameBackups,
  runRcon,
  parsePlayers,
  type GameControlSpec,
  type Player,
  type WorldEntry,
  type BackupEntry,
} from "./game-control";

type Result = { ok: true } | { ok: false; error: string };

/** Jobs that must not overlap a control-panel mutation on the same server. */
const EXCLUSIVE_JOBS = [
  "PROVISION",
  "REINSTALL",
  "DELETE",
  "RESIZE",
  "SUSPEND",
  "UNSUSPEND",
  "SNAPSHOT_ROLLBACK",
  "BACKUP_RESTORE",
  "DISK_EXPAND",
] as const;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      status: true,
      hostname: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
      osTemplate: { select: { family: true } },
      gamePlan: { select: { gameFamily: true } },
    },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Resolve the game family (game plan first, then OS template) if it is a game. */
function resolveFamily(server: {
  osTemplate?: { family?: string | null } | null;
  gamePlan?: { gameFamily?: string | null } | null;
}): string | null {
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  return isGameFamily(fam) ? fam : null;
}

function requireSpec(server: Parameters<typeof resolveFamily>[0]): GameControlSpec {
  const family = resolveFamily(server);
  const spec = controlSpec(family);
  if (!spec) throw new Error("This server is not a supported game server.");
  return spec;
}

function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`gamectl:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

async function lifecycleBusy(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
  });
  return n > 0;
}

async function gameJobInflight(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: ["GAME_POWER", "GAME_BACKUP"] as any } },
  });
  return n > 0;
}

/** Never surface credentials or internal detail in a customer-facing error. */
function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  if (/not a supported game server|not enabled|not available|not running|in progress/i.test(msg)) return msg.slice(0, 200);
  if (/timed out|reachable|root password/i.test(msg)) return msg.slice(0, 200);
  return "Could not reach the game server. Please try again shortly.";
}

// ---------------------------------------------------------------------------
// Overview (capabilities the UI renders from)
// ---------------------------------------------------------------------------

export type GameManageView = {
  family: string;
  label: string;
  rconSupported: boolean;
  rconNote: string | null;
  listSupported: boolean;
  running: boolean;
};

export async function getGameManage(
  serverId: string
): Promise<{ ok: true; view: GameManageView } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    const rconSupported = spec.rcon === "source";
    const rconNote =
      spec.rcon === "rust-web"
        ? "Rust uses WebSocket RCON, which is not wired yet — power, logs, schedules and world backups are fully available."
        : spec.rcon === "none"
          ? `${spec.label} has no remote console protocol, so the command box is disabled — power, logs, schedules and world backups still work.`
          : null;
    return {
      ok: true,
      view: {
        family: spec.family,
        label: spec.label,
        rconSupported,
        rconNote,
        listSupported: rconSupported && !!spec.listCommand,
        running: server.status === "RUNNING",
      },
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// ---------------------------------------------------------------------------
// Power (GAME_POWER job)
// ---------------------------------------------------------------------------

export async function gamePower(serverId: string, action: string): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    if (!isPowerAction(action)) return { ok: false, error: "Unsupported action." };
    const limited = throttle(user.id, "power", 20);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The VM must be running to control the game service." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };
    if (await gameJobInflight(server.id))
      return { ok: false, error: "A game control action is already in progress on this server." };

    await db.job.create({
      data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: action === "restart" } },
    });
    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.power", detail: `${action} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// ---------------------------------------------------------------------------
// Live console: logs (inline read) + RCON command
// ---------------------------------------------------------------------------

export async function getGameLogs(
  serverId: string
): Promise<{ ok: true; lines: string[]; unit: string | null } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    const limited = throttle(user.id, "logs", 40);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) {
      return {
        ok: true,
        unit: spec.serviceHints[0],
        lines: [
          `[${new Date().toISOString()}] [Server thread/INFO]: Starting ${spec.label} server`,
          `[${new Date().toISOString()}] [Server thread/INFO]: Loading world`,
          `[${new Date().toISOString()}] [Server thread/INFO]: Done — sandbox synthetic log (no VM was contacted).`,
        ],
      };
    }
    if (server.status !== "RUNNING")
      return { ok: false, error: "Logs are available only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec));
    return res.ok ? { ok: true, lines: res.lines, unit: res.unit } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function sendGameCommand(
  serverId: string,
  command: string
): Promise<{ ok: true; response: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.rcon !== "source")
      return { ok: false, error: `Remote console commands are not available for ${spec.label}.` };
    const valid = validateRconCommand(command);
    if (!valid.ok) return { ok: false, error: valid.error };
    const limited = throttle(user.id, "rcon", 30);
    if (limited) return { ok: false, error: limited };

    if (SANDBOX) return { ok: true, response: `(sandbox) ran: ${valid.command}` };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The server must be running to send console commands." };

    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.rcon", detail: `${spec.family}: ${valid.command.slice(0, 120)}` },
    });
    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, valid.command));
    return res.ok ? { ok: true, response: res.response } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// ---------------------------------------------------------------------------
// Players (RCON list / kick / ban)
// ---------------------------------------------------------------------------

export async function getGamePlayers(
  serverId: string
): Promise<{ ok: true; players: Player[]; raw: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.rcon !== "source" || !spec.listCommand)
      return { ok: false, error: `Player list is not available for ${spec.label}.` };
    const limited = throttle(user.id, "players", 40);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX)
      return { ok: true, players: [{ name: "steve" }, { name: "alex" }], raw: "There are 2 of a max of 20 players online: steve, alex" };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The player list is available only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, spec.listCommand!));
    if (!res.ok) return { ok: false, error: res.error };
    const parsed = parsePlayers(spec.family, res.response);
    return { ok: true, players: parsed.players, raw: parsed.raw };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

async function playerAction(serverId: string, playerId: string, kind: "kick" | "ban"): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    const template = kind === "kick" ? spec.kickCommand : spec.banCommand;
    if (spec.rcon !== "source" || !template)
      return { ok: false, error: `${kind === "kick" ? "Kick" : "Ban"} is not available for ${spec.label}.` };
    const valid = validatePlayerId(playerId);
    if (!valid.ok) return { ok: false, error: valid.error };
    const limited = throttle(user.id, "player-action", 20);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX) return { ok: true };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };

    const command = template.replace("%s", valid.id);
    await db.auditLog.create({
      data: { userId: user.id, action: `gameserver.${kind}`, detail: `${spec.family}: ${valid.id}` },
    });
    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
    return res.ok ? { ok: true } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function kickPlayer(serverId: string, playerId: string): Promise<Result> {
  return playerAction(serverId, playerId, "kick");
}
export async function banPlayer(serverId: string, playerId: string): Promise<Result> {
  return playerAction(serverId, playerId, "ban");
}

// ---------------------------------------------------------------------------
// World / saves
// ---------------------------------------------------------------------------

export async function getGameWorlds(
  serverId: string
): Promise<{ ok: true; dir: string | null; entries: WorldEntry[] } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    const limited = throttle(user.id, "worlds", 30);
    if (limited) return { ok: false, error: limited };
    if (SANDBOX)
      return {
        ok: true,
        dir: spec.dataRoots[0],
        entries: [
          { name: "world", sizeBytes: 48_312_112, isDir: true },
          { name: "world_nether", sizeBytes: 12_004_233, isDir: true },
          { name: "server.properties", sizeBytes: 1_342, isDir: false },
        ],
      };
    if (server.status !== "RUNNING")
      return { ok: false, error: "Save files are listable only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => readWorlds(conn, spec));
    return res.ok ? { ok: true, dir: res.dir, entries: res.entries } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export type GameBackupRow = BackupEntry & { downloadUrl: string };

export async function getGameBackups(
  serverId: string
): Promise<{ ok: true; backups: GameBackupRow[] } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    const limited = throttle(user.id, "backups", 30);
    if (limited) return { ok: false, error: limited };
    const toRow = (b: BackupEntry): GameBackupRow => ({
      ...b,
      downloadUrl: `/api/files/${serverId}?path=${encodeURIComponent(b.path)}&download=1`,
    });
    if (SANDBOX) {
      const b: BackupEntry = {
        name: "minecraft-20260812-020000.tar.gz",
        path: "/var/backups/nxeon-game/minecraft-20260812-020000.tar.gz",
        sizeBytes: 51_204_884,
        modifiedMs: Date.now() - 3_600_000,
      };
      return { ok: true, backups: [toRow(b)] };
    }
    if (server.status !== "RUNNING")
      return { ok: false, error: "Backups are listable only while the server is running." };
    const res = await withServerSsh(server as SftpServer, (conn) => readGameBackups(conn));
    return res.ok ? { ok: true, backups: res.backups.map(toRow) } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createGameBackup(serverId: string): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    const limited = throttle(user.id, "backup-create", 6);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The VM must be running to back up the world." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };
    if (await gameJobInflight(server.id))
      return { ok: false, error: "A game control action is already in progress on this server." };

    await db.job.create({ data: { type: "GAME_BACKUP", serverId: server.id, payload: {} } });
    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.backup", detail: `world backup on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

// ---------------------------------------------------------------------------
// Scheduled restarts (GameSchedule CRUD)
// ---------------------------------------------------------------------------

export type ScheduleRow = {
  id: string;
  hour: number;
  minute: number;
  enabled: boolean;
  announce: boolean;
  nextRunAt: string | null;
  lastRunAt: string | null;
};

/** Next UTC occurrence of hour:minute strictly after `from`. */
export function computeNextRun(hour: number, minute: number, from: Date = new Date()): Date {
  const next = new Date(
    Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate(), hour, minute, 0, 0)
  );
  if (next.getTime() <= from.getTime()) next.setUTCDate(next.getUTCDate() + 1);
  return next;
}

function rowOut(s: {
  id: string;
  hour: number;
  minute: number;
  enabled: boolean;
  announce: boolean;
  nextRunAt: Date | null;
  lastRunAt: Date | null;
}): ScheduleRow {
  return {
    id: s.id,
    hour: s.hour,
    minute: s.minute,
    enabled: s.enabled,
    announce: s.announce,
    nextRunAt: s.nextRunAt ? s.nextRunAt.toISOString() : null,
    lastRunAt: s.lastRunAt ? s.lastRunAt.toISOString() : null,
  };
}

function validTime(hour: number, minute: number): boolean {
  return Number.isInteger(hour) && hour >= 0 && hour <= 23 && Number.isInteger(minute) && minute >= 0 && minute <= 59;
}

/** Cap on schedules per server (a daily restart or three is the realistic case). */
const MAX_SCHEDULES = 8;

export async function listGameSchedules(
  serverId: string
): Promise<{ ok: true; schedules: ScheduleRow[] } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    requireSpec(server);
    const rows = await db.gameSchedule.findMany({ where: { serverId }, orderBy: [{ hour: "asc" }, { minute: "asc" }] });
    return { ok: true, schedules: rows.map(rowOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createGameSchedule(
  serverId: string,
  hour: number,
  minute: number,
  announce: boolean
): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    requireSpec(server);
    if (!validTime(hour, minute)) return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };
    const limited = throttle(user.id, "sched", 30);
    if (limited) return { ok: false, error: limited };
    const count = await db.gameSchedule.count({ where: { serverId } });
    if (count >= MAX_SCHEDULES) return { ok: false, error: `You can have at most ${MAX_SCHEDULES} schedules.` };

    await db.gameSchedule.create({
      data: {
        serverId,
        kind: "restart",
        hour: Math.trunc(hour),
        minute: Math.trunc(minute),
        announce: !!announce,
        enabled: true,
        nextRunAt: computeNextRun(Math.trunc(hour), Math.trunc(minute)),
      },
    });
    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.schedule.create", detail: `${hour}:${minute} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

async function ownedSchedule(id: string) {
  const user = await requireUser();
  const sched = await db.gameSchedule.findUnique({ where: { id }, include: { server: { select: { userId: true } } } });
  if (!sched) throw new Error("Not found");
  if (sched.server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, sched };
}

export async function updateGameSchedule(
  id: string,
  patch: { hour?: number; minute?: number; enabled?: boolean; announce?: boolean }
): Promise<Result> {
  try {
    const { user, sched } = await ownedSchedule(id);
    const hour = patch.hour ?? sched.hour;
    const minute = patch.minute ?? sched.minute;
    if (!validTime(hour, minute)) return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };
    const enabled = patch.enabled ?? sched.enabled;

    await db.gameSchedule.update({
      where: { id },
      data: {
        hour: Math.trunc(hour),
        minute: Math.trunc(minute),
        enabled,
        announce: patch.announce ?? sched.announce,
        // Recompute the next run so an edit or re-enable takes effect immediately;
        // a disabled schedule carries no next run so the sweep skips it.
        nextRunAt: enabled ? computeNextRun(Math.trunc(hour), Math.trunc(minute)) : null,
      },
    });
    await db.auditLog.create({ data: { userId: user.id, action: "gameserver.schedule.update", detail: id } });
    revalidatePath(`/dashboard/servers/${sched.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function deleteGameSchedule(id: string): Promise<Result> {
  try {
    const { user, sched } = await ownedSchedule(id);
    await db.gameSchedule.delete({ where: { id } });
    await db.auditLog.create({ data: { userId: user.id, action: "gameserver.schedule.delete", detail: id } });
    revalidatePath(`/dashboard/servers/${sched.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

