"use client";

import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import {
  getGameManage,
  gamePower,
  getGameLogs,
  sendGameCommand,
  getGamePlayers,
  kickPlayer,
  banPlayer,
  getGameWorlds,
  getGameBackups,
  createGameBackup,
  listGameSchedules,
  createGameSchedule,
  updateGameSchedule,
  deleteGameSchedule,
  type GameManageView,
  type ScheduleRow,
  type GameBackupRow,
} from "@/lib/actions-game-control";
import type { Player, WorldEntry } from "@/lib/game-control";

/**
 * "Manage" tab for a game server — a Pterodactyl/Nitrado-style control panel over
 * the customer's own game VM: game-service power, a live console (log tail + RCON
 * command box), connected-player list with kick/ban, world/save listing + backup,
 * and scheduled automatic restarts. Every action calls an ownership-guarded,
 * validated server action in lib/actions-game-control.ts.
 */

const SUBTABS = [
  { key: "power", label: "Power & Console" },
  { key: "players", label: "Players" },
  { key: "worlds", label: "Worlds & Backups" },
  { key: "schedules", label: "Scheduled restarts" },
] as const;

function fmtBytes(n: number): string {
  if (!n) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(Math.floor(Math.log(n) / Math.log(1024)), u.length - 1);
  return `${(n / 1024 ** i).toFixed(i ? 1 : 0)} ${u[i]}`;
}
function hhmm(h: number, m: number): string {
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

export function GameManage({ serverId }: { serverId: string }) {
  const [tab, setTab] = useState<string>("power");
  const [view, setView] = useState<GameManageView | null>(null);
  const [loadErr, setLoadErr] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    getGameManage(serverId).then((r) => {
      if (!alive) return;
      if (r.ok) setView(r.view);
      else setLoadErr(r.error);
    });
    return () => {
      alive = false;
    };
  }, [serverId]);

  if (loadErr) return <div className="card text-sm text-red-400">{loadErr}</div>;
  if (!view) return <div className="card text-sm text-slate-400">Loading control panel…</div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="font-semibold">{view.label} control panel</h2>
          <p className="mt-0.5 text-sm text-slate-400">
            Manage your running {view.label} server — power, live console, players, worlds and restarts.
          </p>
        </div>
        {!view.running && (
          <span className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-2.5 py-1 text-xs text-amber-300">
            VM not running — most actions are unavailable
          </span>
        )}
      </div>

      {view.rconNote && (
        <div className="rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-2.5 text-xs text-slate-400">
          {view.rconNote}
        </div>
      )}

      <div className="flex flex-wrap gap-1.5">
        {SUBTABS.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
                  : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "power" && <PowerConsole serverId={serverId} view={view} />}
        {tab === "players" && <Players serverId={serverId} view={view} />}
        {tab === "worlds" && <Worlds serverId={serverId} view={view} />}
        {tab === "schedules" && <Schedules serverId={serverId} />}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Power + live console
// ---------------------------------------------------------------------------

function PowerConsole({ serverId, view }: { serverId: string; view: GameManageView }) {
  const [lines, setLines] = useState<string[]>([]);
  const [logErr, setLogErr] = useState<string | null>(null);
  const [cmd, setCmd] = useState("");
  const [feed, setFeed] = useState<string[]>([]);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const [sending, startSend] = useTransition();
  const logBox = useRef<HTMLPreElement>(null);

  const refreshLogs = useCallback(() => {
    getGameLogs(serverId).then((r) => {
      if (r.ok) {
        setLines(r.lines);
        setLogErr(null);
      } else setLogErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    if (!view.running) return;
    refreshLogs();
    const t = setInterval(refreshLogs, 8000);
    return () => clearInterval(t);
  }, [view.running, refreshLogs]);

  useEffect(() => {
    if (logBox.current) logBox.current.scrollTop = logBox.current.scrollHeight;
  }, [lines]);

  function power(action: "start" | "stop" | "restart") {
    start(async () => {
      setMsg(null);
      const r = await gamePower(serverId, action);
      setMsg(r.ok ? `${action[0].toUpperCase()}${action.slice(1)} requested — watch the console for progress.` : r.error);
    });
  }

  function send() {
    const c = cmd.trim();
    if (!c) return;
    startSend(async () => {
      const r = await sendGameCommand(serverId, c);
      setFeed((f) => [...f.slice(-40), `> ${c}`, r.ok ? r.response || "(no output)" : `! ${r.error}`]);
      setCmd("");
    });
  }

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="font-semibold">Game service power</h3>
        <p className="mt-1 text-sm text-slate-400">
          Starts, stops or restarts the game process itself — separate from powering the whole VM off.
        </p>
        <div className="mt-4 flex flex-wrap gap-2">
          <button className="btn-primary" disabled={pending || !view.running} onClick={() => power("start")}>
            Start
          </button>
          <button className="btn-secondary" disabled={pending || !view.running} onClick={() => power("restart")}>
            Restart
          </button>
          <button className="btn-secondary" disabled={pending || !view.running} onClick={() => power("stop")}>
            Stop
          </button>
        </div>
        {msg && <p className="mt-3 text-sm text-slate-300">{msg}</p>}
      </div>

      <div className="card">
        <div className="flex items-center justify-between">
          <h3 className="font-semibold">Live console</h3>
          <button className="text-xs text-slate-400 hover:text-white" onClick={refreshLogs} disabled={!view.running}>
            Refresh
          </button>
        </div>
        {logErr && <p className="mt-2 text-sm text-amber-300">{logErr}</p>}
        <pre
          ref={logBox}
          className="mt-3 max-h-80 overflow-auto rounded-xl border border-white/[0.06] bg-navy-950/80 p-3 font-mono text-[11px] leading-relaxed text-slate-300"
        >
          {lines.length ? lines.join("\n") : view.running ? "Waiting for logs…" : "Start the server to see logs."}
        </pre>

        {feed.length > 0 && (
          <pre className="mt-3 max-h-48 overflow-auto rounded-xl border border-brand-500/20 bg-navy-950/60 p-3 font-mono text-[11px] leading-relaxed text-slate-300">
            {feed.join("\n")}
          </pre>
        )}

        <div className="mt-3 flex gap-2">
          <input
            className="input flex-1 font-mono text-xs"
            placeholder={
              view.rconSupported ? "Type a console/RCON command (e.g. say hello)…" : "Console commands are not available for this game"
            }
            value={cmd}
            disabled={!view.rconSupported || sending || !view.running}
            onChange={(e) => setCmd(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && send()}
          />
          <button className="btn-primary" disabled={!view.rconSupported || sending || !view.running || !cmd.trim()} onClick={send}>
            {sending ? "Sending…" : "Send"}
          </button>
        </div>
        {!view.rconSupported && (
          <p className="mt-2 text-xs text-slate-500">
            The command box is disabled because this game has no wired remote-console protocol.
          </p>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Players
// ---------------------------------------------------------------------------

function Players({ serverId, view }: { serverId: string; view: GameManageView }) {
  const [players, setPlayers] = useState<Player[]>([]);
  const [raw, setRaw] = useState("");
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const r = await getGamePlayers(serverId);
      if (r.ok) {
        setPlayers(r.players);
        setRaw(r.raw);
        setErr(null);
      } else setErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    if (view.listSupported && view.running) refresh();
  }, [view.listSupported, view.running, refresh]);

  if (!view.listSupported) {
    return <div className="card text-sm text-slate-400">Player list is not available for {view.label}.</div>;
  }

  function act(kind: "kick" | "ban", id: string) {
    start(async () => {
      const r = kind === "kick" ? await kickPlayer(serverId, id) : await banPlayer(serverId, id);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }

  return (
    <div className="card">
      <div className="flex items-center justify-between">
        <h3 className="font-semibold">Connected players</h3>
        <button className="text-xs text-slate-400 hover:text-white" onClick={refresh} disabled={pending || !view.running}>
          Refresh
        </button>
      </div>
      {err && <p className="mt-2 text-sm text-amber-300">{err}</p>}
      {players.length === 0 ? (
        <p className="mt-3 text-sm text-slate-400">{pending ? "Loading…" : "No players connected."}</p>
      ) : (
        <ul className="mt-3 divide-y divide-white/[0.06]">
          {players.map((p) => (
            <li key={p.name} className="flex items-center justify-between py-2 text-sm">
              <span>
                <span className="font-medium">{p.name}</span>
                {p.extra && <span className="ml-2 text-xs text-slate-500">{p.extra}</span>}
              </span>
              <span className="flex gap-2">
                <button className="text-xs text-slate-400 hover:text-white" onClick={() => act("kick", p.name)}>
                  Kick
                </button>
                <button className="text-xs text-red-400 hover:text-red-300" onClick={() => act("ban", p.name)}>
                  Ban
                </button>
              </span>
            </li>
          ))}
        </ul>
      )}
      {raw && (
        <details className="mt-3">
          <summary className="cursor-pointer text-xs text-slate-500">Raw server response</summary>
          <pre className="mt-2 overflow-auto rounded-lg bg-navy-950/70 p-2 font-mono text-[11px] text-slate-400">{raw}</pre>
        </details>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Worlds & backups
// ---------------------------------------------------------------------------

function Worlds({ serverId, view }: { serverId: string; view: GameManageView }) {
  const [entries, setEntries] = useState<WorldEntry[]>([]);
  const [dir, setDir] = useState<string | null>(null);
  const [backups, setBackups] = useState<GameBackupRow[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const [w, b] = await Promise.all([getGameWorlds(serverId), getGameBackups(serverId)]);
      if (w.ok) {
        setEntries(w.entries);
        setDir(w.dir);
      } else setErr(w.error);
      if (b.ok) setBackups(b.backups);
    });
  }, [serverId]);

  useEffect(() => {
    if (view.running) refresh();
  }, [view.running, refresh]);

  function backup() {
    start(async () => {
      setMsg(null);
      const r = await createGameBackup(serverId);
      setMsg(r.ok ? "Backup started — it will appear below when ready (you'll also get a notification)." : r.error);
    });
  }

  return (
    <div className="space-y-6">
      <div className="card">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-semibold">World & save files</h3>
            {dir && <p className="mt-0.5 font-mono text-xs text-slate-500">{dir}</p>}
          </div>
          <div className="flex gap-2">
            <button className="text-xs text-slate-400 hover:text-white" onClick={refresh} disabled={pending || !view.running}>
              Refresh
            </button>
            <button className="btn-primary" onClick={backup} disabled={pending || !view.running}>
              Back up world
            </button>
          </div>
        </div>
        {err && <p className="mt-2 text-sm text-amber-300">{err}</p>}
        {msg && <p className="mt-2 text-sm text-emerald-400">{msg}</p>}
        {entries.length === 0 ? (
          <p className="mt-3 text-sm text-slate-400">{pending ? "Loading…" : "No save files found."}</p>
        ) : (
          <ul className="mt-3 divide-y divide-white/[0.06]">
            {entries.map((e) => (
              <li key={e.name} className="flex items-center justify-between py-2 text-sm">
                <span className="flex items-center gap-2">
                  <span className="text-slate-500">{e.isDir ? "📁" : "📄"}</span>
                  <span className="font-mono text-xs">{e.name}</span>
                </span>
                <span className="text-xs text-slate-400">{fmtBytes(e.sizeBytes)}</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="card">
        <h3 className="font-semibold">World backups</h3>
        {backups.length === 0 ? (
          <p className="mt-3 text-sm text-slate-400">No backups yet. Use “Back up world” above to create one.</p>
        ) : (
          <table className="table-shell mt-3">
            <thead>
              <tr>
                <th>Backup</th>
                <th>Size</th>
                <th>Created</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {backups.map((b) => (
                <tr key={b.path}>
                  <td className="font-mono text-xs">{b.name}</td>
                  <td className="text-xs">{fmtBytes(b.sizeBytes)}</td>
                  <td className="text-xs text-slate-400">{new Date(b.modifiedMs).toLocaleString()}</td>
                  <td>
                    <a className="text-xs text-brand-400 hover:text-brand-300" href={b.downloadUrl}>
                      Download
                    </a>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        <p className="mt-3 text-xs text-slate-500">
          Restoring or uploading a world is coming soon — for now, download a backup here and restore via the Files tab.
        </p>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Scheduled restarts
// ---------------------------------------------------------------------------

function Schedules({ serverId }: { serverId: string }) {
  const [rows, setRows] = useState<ScheduleRow[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [hour, setHour] = useState(4);
  const [minute, setMinute] = useState(0);
  const [announce, setAnnounce] = useState(true);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    listGameSchedules(serverId).then((r) => {
      if (r.ok) setRows(r.schedules);
      else setErr(r.error);
    });
  }, [serverId]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  function add() {
    start(async () => {
      setErr(null);
      const r = await createGameSchedule(serverId, hour, minute, announce);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }
  function toggle(row: ScheduleRow) {
    start(async () => {
      const r = await updateGameSchedule(row.id, { enabled: !row.enabled });
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }
  function remove(id: string) {
    start(async () => {
      const r = await deleteGameSchedule(id);
      if (!r.ok) setErr(r.error);
      else refresh();
    });
  }

  return (
    <div className="card">
      <h3 className="font-semibold">Automatic restarts</h3>
      <p className="mt-1 text-sm text-slate-400">
        Restart the game server automatically at a set time each day (UTC). Players are warned over RCON first where supported.
      </p>
      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}

      <div className="mt-4 flex flex-wrap items-end gap-3">
        <label className="text-sm">
          <span className="mb-1 block font-medium">Time (UTC)</span>
          <span className="flex items-center gap-1">
            <select className="input w-20" value={hour} onChange={(e) => setHour(Number(e.target.value))}>
              {Array.from({ length: 24 }, (_, i) => (
                <option key={i} value={i}>
                  {String(i).padStart(2, "0")}
                </option>
              ))}
            </select>
            <span>:</span>
            <select className="input w-20" value={minute} onChange={(e) => setMinute(Number(e.target.value))}>
              {[0, 15, 30, 45].map((m) => (
                <option key={m} value={m}>
                  {String(m).padStart(2, "0")}
                </option>
              ))}
            </select>
          </span>
        </label>
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" checked={announce} onChange={(e) => setAnnounce(e.target.checked)} />
          Warn players first
        </label>
        <button className="btn-primary" onClick={add} disabled={pending}>
          Add schedule
        </button>
      </div>

      {rows.length === 0 ? (
        <p className="mt-4 text-sm text-slate-400">No schedules yet.</p>
      ) : (
        <ul className="mt-4 divide-y divide-white/[0.06]">
          {rows.map((r) => (
            <li key={r.id} className="flex flex-wrap items-center justify-between gap-2 py-2.5 text-sm">
              <span className="flex items-center gap-3">
                <span className="font-mono">{hhmm(r.hour, r.minute)} UTC</span>
                <span className={`text-xs ${r.enabled ? "text-emerald-400" : "text-slate-500"}`}>
                  {r.enabled ? "enabled" : "paused"}
                </span>
                {r.announce && <span className="text-xs text-slate-500">warns players</span>}
                {r.enabled && r.nextRunAt && (
                  <span className="text-xs text-slate-500">next: {new Date(r.nextRunAt).toLocaleString()}</span>
                )}
              </span>
              <span className="flex gap-3">
                <button className="text-xs text-slate-400 hover:text-white" onClick={() => toggle(r)} disabled={pending}>
                  {r.enabled ? "Pause" : "Resume"}
                </button>
                <button className="text-xs text-red-400 hover:text-red-300" onClick={() => remove(r.id)} disabled={pending}>
                  Remove
                </button>
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

